import re
def _bun_lock_dependency_version(path: Path) -> str:
    try:
        content = path.read_text(encoding="utf-8")
    except OSError:
        return ""
    match = re.search(r'"@opencode-ai/plugin"\s*:\s*"([^"]+)"', content)
    return match.group(1) if match else ""


